public static class StorageSiloAssetBuilder {
 const string Root="Assets/_Anseong/Art/Environment/Assets/StorageSilo";
 static readonly List<GameObject> pieces=new List<GameObject>();
 static void Folder(string p){if(AssetDatabase.IsValidFolder(p))return;var parent=Path.GetDirectoryName(p).Replace('\\','/');Folder(parent);AssetDatabase.CreateFolder(parent,Path.GetFileName(p));}
 static Material Mat(string name,Color color){var existing=AssetDatabase.LoadAssetAtPath<Material>(Root+"/"+name+".mat");if(existing){existing.color=color;return existing;}var m=new Material(Shader.Find("Universal Render Pipeline/Lit"));m.color=color;m.SetFloat("_Smoothness",.08f);m.enableInstancing=true;AssetDatabase.CreateAsset(m,Root+"/"+name+".mat");return m;}
 static void Box(Transform parent,string name,Vector3 pos,Vector3 size,Material mat){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=name;g.transform.SetParent(parent,false);g.transform.localPosition=pos;g.transform.localScale=size;g.GetComponent<Renderer>().sharedMaterial=mat;Object.DestroyImmediate(g.GetComponent<Collider>());pieces.Add(g);}
 static Mesh Bake(Transform root,Material[] materials){var temps=new List<Mesh>();var final=new CombineInstance[materials.Length];for(int i=0;i<materials.Length;i++){var list=new List<CombineInstance>();foreach(var g in pieces)if(g.GetComponent<Renderer>().sharedMaterial==materials[i])list.Add(new CombineInstance{mesh=g.GetComponent<MeshFilter>().sharedMesh,transform=root.worldToLocalMatrix*g.transform.localToWorldMatrix});var part=new Mesh();part.CombineMeshes(list.ToArray(),true,true);temps.Add(part);final[i]=new CombineInstance{mesh=part,transform=Matrix4x4.identity};}var mesh=new Mesh{name="StorageSilo"};mesh.CombineMeshes(final,false,true);mesh.RecalculateBounds();foreach(var m in temps)Object.DestroyImmediate(m);return mesh;}
 static void Beam(Transform root,string name,Vector3 a,Vector3 b,float width,Material material){Box(root,name,(a+b)*.5f,new Vector3(width,(b-a).magnitude,width),material);pieces[pieces.Count-1].transform.localRotation=Quaternion.FromToRotation(Vector3.up,b-a);}
 static Mesh Lathe(List<Vector2> profile,int sides){var v=new List<Vector3>();var uv=new List<Vector2>();var t=new List<int>();for(int j=0;j<profile.Count;j++)for(int i=0;i<=sides;i++){float a=i*2*Mathf.PI/sides;v.Add(new Vector3(Mathf.Sin(a)*profile[j].y,profile[j].x,Mathf.Cos(a)*profile[j].y));uv.Add(new Vector2(i/(float)sides,profile[j].x/26));}for(int j=0;j<profile.Count-1;j++)for(int i=0;i<sides;i++){int n=j*(sides+1)+i;t.AddRange(new[]{n,n+1,n+sides+1,n+1,n+sides+2,n+sides+1});}var m=new Mesh();m.SetVertices(v);m.SetUVs(0,uv);m.SetTriangles(t,0);m.RecalculateNormals();m.RecalculateBounds();return m;}
 static void Part(Transform r,string name,Mesh mesh,Material mat){var g=new GameObject(name,typeof(MeshFilter),typeof(MeshRenderer));g.transform.SetParent(r,false);g.GetComponent<MeshFilter>().sharedMesh=mesh;g.GetComponent<Renderer>().sharedMaterial=mat;pieces.Add(g);}
 static void FinishMetal(Material m){var tex=new Texture2D(512,512,TextureFormat.RGB24,false);var rand=new System.Random(91);for(int y=0;y<512;y++)for(int x=0;x<512;x++){float n=(float)rand.NextDouble();float f=.87f+n*.1f-Mathf.PerlinNoise(x*.09f,y*.01f)*.07f;bool joint=x%64<1;Color c=joint?new Color(.61f,.58f,.51f):new Color(f,f*.99f,f*.95f);if(y<12&&n>.5f)c*=.84f;tex.SetPixel(x,y,c);}tex.Apply();string p=Root+"/GalvanizedWeathering.png";File.WriteAllBytes(p,tex.EncodeToPNG());Object.DestroyImmediate(tex);AssetDatabase.ImportAsset(p);m.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture2D>(p));m.SetFloat("_Metallic",.48f);m.SetFloat("_Smoothness",.29f);EditorUtility.SetDirty(m);}
 [MenuItem("Anseong/Art/Build Storage Silo")]
 public static void Build(){Folder(Root);pieces.Clear();var paint=Mat("GalvanizedShell",new Color(.76f,.75f,.69f));var steel=Mat("StructuralSteel",new Color(.22f,.26f,.27f));var dark=Mat("Openings",new Color(.12f,.14f,.14f));var trim=Mat("WeatheredSeams",new Color(.49f,.40f,.29f));FinishMetal(paint);var root=new GameObject("StorageSilo");var r=root.transform;var meshes=new List<Mesh>();
 var profile=new List<Vector2>();for(int j=0;j<=192;j++){float y=Mathf.Lerp(3.5f,22,j/192f);float radius=6+(j%2==0?.035f:-.035f);profile.Add(new Vector2(y,radius));}var shell=Lathe(profile,48);meshes.Add(shell);Part(r,"CorrugatedShell",shell,paint);
 var roof=Lathe(new List<Vector2>{new Vector2(22,6.12f),new Vector2(22.12f,6.12f),new Vector2(25.6f,.8f),new Vector2(25.7f,.8f),new Vector2(25.7f,0)},64);meshes.Add(roof);Part(r,"ConicalRoof",roof,paint);
 var hopper=Lathe(new List<Vector2>{new Vector2(1.7f,.42f),new Vector2(2,.42f),new Vector2(3.5f,5.85f)},64);meshes.Add(hopper);Part(r,"LowerHopper",hopper,steel);
 foreach(float y in new[]{3.5f,9.65f,15.85f,22f}){var band=Lathe(new List<Vector2>{new Vector2(y-.055f,6.065f),new Vector2(y+.055f,6.065f)},64);meshes.Add(band);Part(r,"PanelCourseRing",band,trim);}
 for(int i=0;i<16;i++){float a=i*Mathf.PI*2/16;Beam(r,"RoofStandingSeam",new Vector3(Mathf.Sin(a)*6.13f,22.14f,Mathf.Cos(a)*6.13f),new Vector3(Mathf.Sin(a)*.82f,25.64f,Mathf.Cos(a)*.82f),.045f,trim);}
 for(int i=0;i<6;i++){float a=i*Mathf.PI*2/6;var p=new Vector3(Mathf.Sin(a)*5.35f,0,Mathf.Cos(a)*5.35f);Box(r,"LegBasePlate",p+Vector3.up*.08f,new Vector3(.95f,.16f,.95f),steel);Box(r,"SteelSupportLeg",p+Vector3.up*2.1f,new Vector3(.34f,4.2f,.42f),steel);Beam(r,"LegKneeBrace",p+Vector3.up*1.8f,p*.88f+Vector3.up*3.8f,.20f,steel);}
 Box(r,"DischargeNeck",new Vector3(0,1.5f,0),new Vector3(.8f,.8f,.8f),steel);Box(r,"ValveFlange",new Vector3(0,1.08f,0),new Vector3(1.15f,.12f,1.15f),trim);
 for(int side=-1;side<=1;side+=2)Beam(r,"AccessLadderRail",new Vector3(side*.32f,.3f,-6.35f),new Vector3(side*.32f,23,-6.35f),.065f,steel);for(int i=0;i<69;i++)Beam(r,"LadderRung",new Vector3(-.32f,.4f+i*.33f,-6.35f),new Vector3(.32f,.4f+i*.33f,-6.35f),.045f,steel);
 Box(r,"InspectionPlatform",new Vector3(0,22.15f,-6.7f),new Vector3(2.4f,.12f,1.7f),steel);for(int side=-1;side<=1;side+=2){Beam(r,"PlatformRail",new Vector3(side*1.15f,23.3f,-7.5f),new Vector3(side*1.15f,23.3f,-5.95f),.07f,steel);for(int z=0;z<2;z++)Beam(r,"RailPost",new Vector3(side*1.15f,22.2f,-7.5f+z*1.55f),new Vector3(side*1.15f,23.3f,-7.5f+z*1.55f),.07f,steel);}Beam(r,"PlatformOuterRail",new Vector3(-1.15f,23.3f,-7.5f),new Vector3(1.15f,23.3f,-7.5f),.07f,steel);
 Box(r,"InspectionHatch",new Vector3(1,5,-6.06f),new Vector3(.65f,.9f,.10f),trim);Box(r,"HatchInset",new Vector3(1,5,-6.12f),new Vector3(.5f,.73f,.035f),steel);
 var mats=new[]{paint,steel,dark,trim};Box(r,"DischargeOpening",new Vector3(0,1.015f,0),new Vector3(.58f,.015f,.58f),dark);var mesh=Bake(r,mats);mesh.name="StorageSilo";var old=AssetDatabase.LoadAssetAtPath<Mesh>(Root+"/StorageSilo.asset");if(old){EditorUtility.CopySerialized(mesh,old);Object.DestroyImmediate(mesh);mesh=old;mesh.UploadMeshData(false);}else AssetDatabase.CreateAsset(mesh,Root+"/StorageSilo.asset");foreach(var p in pieces)Object.DestroyImmediate(p);pieces.Clear();foreach(var m in meshes)Object.DestroyImmediate(m);root.AddComponent<MeshFilter>().sharedMesh=mesh;root.AddComponent<MeshRenderer>().sharedMaterials=mats;
 var bodyCollider=root.AddComponent<CapsuleCollider>();bodyCollider.center=new Vector3(0,12.75f,0);bodyCollider.radius=6.05f;bodyCollider.height=18.5f;for(int i=0;i<6;i++){float a=i*Mathf.PI*2/6;var col=root.AddComponent<BoxCollider>();col.center=new Vector3(Mathf.Sin(a)*5.35f,2.1f,Mathf.Cos(a)*5.35f);col.size=new Vector3(.34f,4.2f,.42f);}var prefab=PrefabUtility.SaveAsPrefabAsset(root,Root+"/StorageSilo.prefab");Object.DestroyImmediate(root);
 Folder("Assets/_Anseong/Scenes/Sandbox");EditorSceneManager.NewScene(NewSceneSetup.DefaultGameObjects,NewSceneMode.Single);PrefabUtility.InstantiatePrefab(prefab);var floor=GameObject.CreatePrimitive(PrimitiveType.Cube);floor.transform.position=new Vector3(0,-.15f,0);floor.transform.localScale=new Vector3(100,.3f,100);floor.GetComponent<Renderer>().sharedMaterial=Mat("PreviewConcrete",new Color(.58f,.60f,.59f));var camera=Camera.main;camera.transform.position=new Vector3(30,18,-36);camera.transform.LookAt(new Vector3(0,12,0));camera.fieldOfView=43;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.35f,.42f,.47f);var sun=Object.FindFirstObjectByType<Light>();sun.intensity=1.4f;sun.transform.rotation=Quaternion.Euler(35,-45,0);RenderSettings.ambientMode=UnityEngine.Rendering.AmbientMode.Flat;RenderSettings.ambientLight=new Color(.55f,.59f,.64f);RenderSettings.fog=false;EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene(),"Assets/_Anseong/Scenes/Sandbox/Sandbox_StorageSilo.unity");AssetDatabase.SaveAssets();Capture(camera);int tris=mesh.triangles.Length/3;if(mesh.bounds.size.y>26||mesh.bounds.size.y<25||tris>40000||prefab.GetComponentsInChildren<Rigidbody>().Length!=0)throw new Exception("Silo check failed");Debug.Log("STORAGE_SILO_PASS triangles="+tris+" dimensions="+mesh.bounds.size+" shellDiameter=12 height=25.7 meshes=1 materials=4 physics=static");} static void Capture(Camera camera){var rt=new RenderTexture(1200,850,24);var old=RenderTexture.active;camera.targetTexture=rt;camera.Render();RenderTexture.active=rt;var image=new Texture2D(1200,850,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,1200,850),0,0);image.Apply();File.WriteAllBytes("C:/Users/Admin/Documents/ChatGPT/안성제철/output/StorageSilo_Preview.png",image.EncodeToPNG());camera.targetTexture=null;RenderTexture.active=old;Object.DestroyImmediate(image);Object.DestroyImmediate(rt);}
